import type { CSSProperties, ReactNode } from 'react'
import './index.less'

interface SolutionSectionProps {
  image: string
  imageAlt?: string
  imageWidth: number
  imageHeight: number
  reverse?: boolean
  children: ReactNode
  className?: string
  style?: CSSProperties
  padding?: string
  gap?: number
  imageBorderRadius?: number
}

const SolutionSection = ({
  image,
  imageAlt = '',
  imageWidth,
  imageHeight,
  reverse = false,
  children,
  className = '',
  style,
  padding,
  gap = 100,
  imageBorderRadius = 16,
}: SolutionSectionProps) => {
  return (
    <section
      className={`solution-section ${reverse ? 'solution-section--reverse' : ''} ${className}`}
      style={{
        ...style,
        ...(padding ? { padding } : {}),
        ...(gap ? { gap: `${gap}px` } : {}),
      }}
    >
      <div
        className="solution-section__image"
        style={{
          width: imageWidth,
          height: imageHeight,
          borderRadius: imageBorderRadius,
        }}
      >
        <img src={image} alt={imageAlt} />
      </div>
      <div className="solution-section__content">{children}</div>
    </section>
  )
}

export default SolutionSection
